"""
BUGFIX: de e-mail-opt-in-bevestigingsmail werd nooit daadwerkelijk
verstuurd -- geen foutmelding op het scherm, gewoon stilzwijgend niks.

Oorzaak: emailer.py las zijn instellingen alleen via os.getenv(...)
(environment-variabelen) -- prima voor de losse GitHub Actions-scripts
(die zo hun GitHub Secrets krijgen), maar de SITE ZELF (dashboard.py, op
Streamlit Cloud) gebruikt een compleet ANDER mechanisme: Streamlit's
eigen st.secrets, gevuld via de app's 'Secrets'-instellingen. Daardoor
bleven EMAIL_ADDRESS/EMAIL_APP_PASSWORD leeg zodra de site zelf een mail
probeerde te versturen, en emailer.py's eigen ingebouwde check
('if not EMAIL_ADDRESS...') gaf dan stil False terug -- geen crash, dus
ook geen zichtbare foutmelding.

emailer.py probeert nu EERST Streamlit Secrets te lezen (als
beschikbaar), en valt anders terug op de env-variabele (hoe het al
werkte voor de GitHub Actions-scripts) -- dus beide contexten werken nu
correct, zonder dat de losse scripts iets hoeven te veranderen.

Gebruik: python fix_emailer_streamlit_secrets_support.py
Draai dit vanuit je stock_screener-map (hestys-fresh).
"""
NEW_CONTENT = '"""\nSimpele, herbruikbare e-mail-notificatiemodule via SMTP. Werkt met Gmail,\nOutlook, en de meeste andere providers.\n\nBELANGRIJK bij Gmail: je normale wachtwoord werkt hier niet als je 2FA\naan hebt staan (aanbevolen). Je hebt een \'app-wachtwoord\' nodig:\n1. Ga naar https://myaccount.google.com/apppasswords\n2. Maak een nieuw app-wachtwoord aan (naam maakt niet uit, bv. "python-bot")\n3. Gebruik dat 16-tekens-wachtwoord hieronder in .env, NIET je normale wachtwoord\n\nBenodigde .env-variabelen:\n  EMAIL_SMTP_SERVER=smtp.gmail.com\n  EMAIL_SMTP_PORT=587\n  EMAIL_ADDRESS=jouw@gmail.com\n  EMAIL_APP_PASSWORD=jouw-16-tekens-app-wachtwoord\n  EMAIL_TO=waar-naartoe@gmail.com   (mag hetzelfde adres zijn als EMAIL_ADDRESS)\n\nVoor Outlook/Hotmail: EMAIL_SMTP_SERVER=smtp.office365.com, poort 587,\nen daar werkt vaak wel gewoon je normale wachtwoord (of ook een app-wachtwoord\nals je 2FA hebt).\n"""\nfrom __future__ import annotations\n\nimport os\nimport smtplib\nfrom email.mime.multipart import MIMEMultipart\nfrom email.mime.text import MIMEText\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# De site zelf (dashboard.py, draaiend op Streamlit Cloud) krijgt zijn\n# instellingen via Streamlit\'s EIGEN secrets-mechanisme (st.secrets), niet\n# via environment-variabelen -- dat is een compleet andere plek dan waar de\n# losse GitHub Actions-scripts (daily_batch.py e.d.) hun instellingen\n# vandaan halen. Zonder deze fallback bleef EMAIL_ADDRESS/EMAIL_APP_PASSWORD\n# stil leeg zodra de site zelf een mail probeerde te versturen (bv. de\n# e-mail-opt-in-bevestiging) -- geen crash, gewoon stilzwijgend niet\n# verstuurd. Nu wordt EERST Streamlit Secrets geprobeerd, en pas als dat\n# niet beschikbaar/ingevuld is, wordt teruggevallen op de env-variabele\n# (hoe het al werkte voor de GitHub Actions-scripts).\ntry:\n    import streamlit as _st\nexcept ImportError:\n    _st = None\n\n\ndef _get_config(env_key: str, secrets_key: str, default: str = "") -> str:\n    if _st is not None:\n        try:\n            value = _st.secrets["email"][secrets_key]\n            if value:\n                return str(value)\n        except Exception:\n            pass\n    return os.getenv(env_key, default)\n\n\nSMTP_SERVER = _get_config("EMAIL_SMTP_SERVER", "smtp_server", "smtp.gmail.com")\nSMTP_PORT = int(_get_config("EMAIL_SMTP_PORT", "smtp_port", "587"))\nEMAIL_ADDRESS = _get_config("EMAIL_ADDRESS", "address", "")\nEMAIL_APP_PASSWORD = _get_config("EMAIL_APP_PASSWORD", "app_password", "")\n\n# EMAIL_TO mag 1 adres zijn, of meerdere gescheiden door een komma, bv.:\n#   EMAIL_TO=jouw@gmail.com,vriend@gmail.com\n_email_to_raw = os.getenv("EMAIL_TO", EMAIL_ADDRESS)\nEMAIL_TO_LIST = [addr.strip() for addr in _email_to_raw.split(",") if addr.strip()]\nEMAIL_TO = ", ".join(EMAIL_TO_LIST)  # voor weergave in de \'To\'-header\n\n\ndef is_configured() -> bool:\n    return bool(EMAIL_ADDRESS and EMAIL_APP_PASSWORD and EMAIL_TO_LIST)\n\n\ndef send_email(subject: str, body_text: str, body_html: str = None, to_email: str = None) -> bool:\n    """\n    Verstuurt een e-mail via BCC: ontvangers zien elkaars adres niet.\n\n    Als \'to_email\' wordt meegegeven, gaat de mail ALLEEN naar dat ene\n    adres (gebruikt door het wekelijkse batch-script, dat elke gebruiker\n    een eigen, persoonlijke mail stuurt). Zonder \'to_email\' wordt de vaste\n    EMAIL_TO_LIST uit .env gebruikt (het oorspronkelijke, single-user-gedrag).\n\n    Geeft True terug bij succes, False bij een fout (de fout wordt ook\n    geprint, zodat je \'m in een logbestand kan terugzien als dit script\n    via een geplande taak draait).\n    """\n    recipients = [to_email] if to_email else EMAIL_TO_LIST\n\n    if not EMAIL_ADDRESS or not EMAIL_APP_PASSWORD or not recipients:\n        print("E-mail niet verstuurd: EMAIL_ADDRESS/EMAIL_APP_PASSWORD/ontvanger(s) "\n              "ontbreken (compleet).")\n        return False\n\n    msg = MIMEMultipart("alternative")\n    msg["Subject"] = subject\n    msg["From"] = EMAIL_ADDRESS\n    msg["To"] = EMAIL_ADDRESS  # BCC: toon alleen jezelf, niet de andere ontvangers\n\n    msg.attach(MIMEText(body_text, "plain"))\n    if body_html:\n        msg.attach(MIMEText(body_html, "html"))\n\n    try:\n        with smtplib.SMTP(SMTP_SERVER, SMTP_PORT, timeout=30) as server:\n            server.starttls()\n            server.login(EMAIL_ADDRESS, EMAIL_APP_PASSWORD)\n            server.sendmail(EMAIL_ADDRESS, recipients, msg.as_string())\n        print(f"E-mail (BCC) verstuurd naar {len(recipients)} ontvanger(s).")\n        return True\n    except Exception as exc:\n        print(f"E-mail versturen mislukt: {exc}")\n        return False\n\n\nif __name__ == "__main__":\n    ok = send_email(\n        subject="Testmail vanuit je trading-tools",\n        body_text="Dit is een testbericht. Als je dit ontvangt, werkt je e-mail-configuratie!",\n    )\n    print("Gelukt!" if ok else "Niet gelukt, zie foutmelding hierboven.")\n'

with open("emailer.py", "w", encoding="utf-8") as f:
    f.write(NEW_CONTENT)
print(f"Klaar. 'emailer.py' overschreven ({len(NEW_CONTENT)} tekens).")
print("git add .")
print('git commit -m "Fix emailer.py to also read from Streamlit Secrets (site could not send email before)"')
print("git push")
